function forgeWeapon(level){if(!state.buildings.forge||level<=state.weapon)return false;let cost=level===1?{'铁锭':5,'木板':3}:{'铁锭':8,'水晶':3,'木板':4};if(!payMaterials(cost)){buildMessage='锻造需要 '+costText(cost);return false}state.weapon=level;updateTool();buildMessage='已锻造并装备 '+weapons[level].name;return true}
function recallBoat(){if(!state.buildings.dock||!state.boatOwned||sailing){buildMessage='需要先下船，再召回帆船。';return false}if(state.money<20){buildMessage='召回需要 20 金币。';return false}state.money-=20;state.boat={x:camp.x+7,z:camp.z+120};state.boatYaw=0;rebuildBuildings();buildMessage='帆船已召回码头。';return true}
function makeBoat(){if(!state.buildings.dock||state.boatOwned)return false;if(!payMaterials({'木板':14,'铁锭':5})){buildMessage='造船需要木板 × 14 + 铁锭 × 5。';return false}state.boatOwned=true;state.boat={x:camp.x+7,z:camp.z+120};state.boatYaw=0;rebuildBuildings();buildMessage='帆船已停靠码头。前往码头末端，按 E 登船。';return true}
function onDock(x,z){return !!state.buildings.dock&&Math.abs(x-camp.x)<3.1&&z>camp.z+59&&z<camp.z+129}
function boardBoat(){if(!state.boatOwned||!state.boat)return false;if(sailing)return leaveBoat();if(Math.hypot(state.x-state.boat.x,state.z-state.boat.z)>18){buildMessage='先前往码头末端，靠近停泊的帆船。';return false}sailing=true;onTower=false;climbing=0;state.x=state.boat.x;state.z=state.boat.z;vy=0;yaw=state.boatYaw||0;buildMessage='已登船。WASD 驾船，E 靠岸下船。星辉岛在东南方 X 850 / Z 850。';notice(buildMessage,7);return true}
function leaveBoat(){if(!sailing)return false;let shore=null;for(let r of [4,7,10,14]){for(let i=0;i<20;i++){let a=i*Math.PI/10,x=state.x+Math.cos(a)*r,z=state.z+Math.sin(a)*r;if(land(x,z)||onDock(x,z)){shore={x,z};break}}if(shore)break}if(!shore){buildMessage='水太深，靠近岸边或码头再下船。';notice(buildMessage);return false}sailing=false;state.x=shore.x;state.z=shore.z;footY=Math.max(terrain(state.x,state.z),0);vy=0;buildMessage='已安全上岸。帆船会停在下船的位置。';notice(buildMessage);save();return true}
function plantGarden(){if(!state.buildings.garden||state.gardenPlanted)return false;if(!payMaterials({'种子':1})){buildMessage='需要 1 颗种子。可用 10 金币购买 3 颗。';return false}state.gardenPlanted=Date.now();buildMessage='播种完成，约 75 秒后成熟。离开游戏也会继续生长。';return true}
function harvestGarden(now=Date.now()){if(!state.buildings.garden||!state.gardenPlanted||now-state.gardenPlanted<75000){buildMessage='作物还没成熟。';return false}state.gardenPlanted=0;state.bag['水果']=(state.bag['水果']||0)+3;state.bag['谷物']=(state.bag['谷物']||0)+2;state.bag['药草']=(state.bag['药草']||0)+2;state.bag['种子']=(state.bag['种子']||0)+1;buildMessage='收获水果 × 3、谷物 × 2、药草 × 2，另保留一颗种子供下次种植。';return true}
function makeSoup(){if(!state.buildings.garden||!payMaterials({'水果':1,'药草':2})){buildMessage='药草汤需要水果 × 1 + 药草 × 2。';return false}state.bag['药草汤']=(state.bag['药草汤']||0)+1;buildMessage='制作了药草汤，可恢复 60 点生命。';return true}
function eatFood(item){if((state.bag[item]||0)<1)return false;let fish=item==='烤鱼'||item==='烤鲨鱼肉';if(state.hp>=healthLimit()&&!fish){buildMessage='生命值已满，食物已为你保留。';return false}state.bag[item]--;if(fish)state.maxHp=healthLimit()+5;state.hp=Math.min(healthLimit(),state.hp+({'番茄':6,'香果':12,'药草汤':60,'椰子':15,'椰子饭':50,'烤鱼':35,'烤鲨鱼肉':45,'绷带':40,'面包':25}[item]||25));stamina=Math.min(100,stamina+30);buildMessage='食用 '+item+'，恢复生命与体力。'+(fish?'生命上限永久 +5（一格）。':'');return true}
function makeAmmo(){if(!state.buildings.turret||!payMaterials({'木头':2,'石料':1})){buildMessage='装填需要木头 × 2 + 石料 × 1。';return false}state.ammo+=12;buildMessage='已制作并装填 12 发石弹。防御塔会自动瞄准海兽。';return true}
function putMuseum(type){if(!state.buildings.museum)return false;let item=kinds[type]?.item;if(!item)return false;if(state.museum[type]){state.museum[type]=false;state.bag[item]=(state.bag[item]||0)+1;buildMessage='展品已取回背包。'}else{if((state.bag[item]||0)<1){buildMessage='需要 '+item+' × 1。';return false}state.bag[item]--;state.museum[type]=true;discoverRock(type);buildMessage=kinds[type].name+' 已放入博物馆展柜。';if(kinds.slice(0,7).every((_,i)=>state.museum[i])&&!state.museumAwarded){state.museumAwarded=true;state.money+=600;buildMessage='七种矿物集齐！获得 600 金币和「地质收藏家」奖杯。'}}rebuildBuildings();return true}
function startClimb(){if(!state.buildings.watchtower||sailing)return false;let p=siteFor('watchtower');if(!onTower&&Math.hypot(state.x-p.x,state.z-p.z)>8){buildMessage='需要先走到瞭望塔脚下。';return false}climbing=onTower?-1:1;state.x=p.x;state.z=p.z;vy=0;towerHeight=Math.max(terrain(p.x,p.z),footY);notice(climbing>0?'正在攀登瞭望塔，使用鼠标或方向键观察。':'正在下塔。');return true}
function markFromTower(){if(!onTower){buildMessage='先爬上瞭望塔，才能使用望远镜标记。';return false}state.markedOre=rocks.filter(r=>!r.dead&&Math.hypot(r.x-state.x,r.z-state.z)<270).sort((a,b)=>(b.type>=3)-(a.type>=3)||Math.hypot(a.x-state.x,a.z-state.z)-Math.hypot(b.x-state.x,b.z-state.z)).slice(0,8).map(r=>({x:r.x,z:r.z,type:r.type}));for(let c of caveDefs)if(Math.hypot(c.x-state.x,c.z-state.z)<300&&!state.caveVisits.includes(c.id))state.caveVisits.push(c.id);buildMessage='已标记 '+state.markedOre.length+' 处矿点，并记录附近洞穴。可在下面选择矿点追踪。';return true}
function buildingInteract(){if(heldItem()==='矿层勘探仪'){useSurvey26();return}if(heldItem()==='稳态传送核心'&&!state.dimension){tab='dimensions';openMenu();return}if(state.dimension){if(Math.hypot(state.x,state.z-12)<4)leaveDimension();else notice('走到返回门旁按 E，或点击上方返回海岛。');return}if(interactAdvanced())return;if(seated){standUp();return}if(interactHouseDoor())return;if(!survey&&!flying&&!menuOpen&&directInteract())return;if(flying){exitAircraft();return}if(state.aircraft&&Math.hypot(state.x-state.aircraft.x,state.z-state.aircraft.z)<7){boardAircraft();return}if(interactPalm())return;if(survey)return notice('按 V 灵魂归位后操作设施');if(sailing){leaveBoat();return}if(climbing)return;if(onTower){startClimb();return}if(!state.insideHouse&&state.boatOwned&&state.boat&&Math.hypot(state.x-state.boat.x,state.z-state.boat.z)<18){boardBoat();return}if(selected?.obj.kind==='facility'){openFacility(selected.obj.id);return}let tower=siteFor('watchtower');if(state.buildings.watchtower&&Math.hypot(state.x-tower.x,state.z-tower.z)<8){startClimb();return}let nearest=facilityAnchors.filter(a=>!a.id.startsWith('treasure:')).map(a=>({a,p:a.group.localToWorld(a.point.clone())})).filter(v=>Math.abs(v.p.y-footY)<(v.a.id.startsWith('room:')||v.a.id.startsWith('house:')?3:9)).sort((a,b)=>Math.hypot(a.p.x-state.x,a.p.z-state.z)-Math.hypot(b.p.x-state.x,b.p.z-state.z))[0];if(nearest&&Math.hypot(nearest.p.x-state.x,nearest.p.z-state.z)<16){openFacility(nearest.a.id);return}facilityFocus=null;tab='build';document.querySelector('nav .active')?.classList.remove('active');document.querySelector('[data-tab="build"]').classList.add('active');openMenu()}
function actionButton(text,action,disabled=false){return `<button data-building-action="${action}" ${disabled?'disabled':''}>${text}</button>`}
function renderBuildings(){if(!facilitySession){renderLockedWorkbench();return}if(facilitySession==='basic'){facilityFocus=null}else if(buildingDefs.some(d=>d.id===facilitySession)){facilityFocus=facilitySession}else{renderLockedWorkbench();return}if(['arsenal','orbital'].includes(facilitySession)){renderAdvancedWorkshop(facilitySession);return}if(facilityFocus&&['sawmill','craftbench'].includes(facilityFocus)&&state.buildings[facilityFocus]){renderWorkshop(facilityFocus);return}$('#menu').classList.remove('workshop-menu');let p=$('#panel');let count=Object.values(state.buildings).filter(Boolean).length;p.innerHTML=`<div class="craftintro"><strong>营地建筑 ${count} / ${buildingDefs.filter(b=>b.id!=='sawmill').length} · 木板 ${state.bag['木板']||0} · 铁锭 ${state.bag['铁锭']||0}</strong><p role="status">${buildMessage}</p></div>`+(facilityFocus?actionButton('← 返回全部建筑','all'):'')+buildingDefs.filter(b=>b.id!=='sawmill'&&(!facilityFocus||b.id===facilityFocus)).map(b=>{let built=state.buildings[b.id],controls='';if(built){if(['kiln','lapidary','kitchen'].includes(b.id)){controls=Object.entries(stationRecipes).filter(([id,r])=>r.station===b.id).map(([id,r])=>actionButton(costText(r.cost)+' → '+r.item+' × '+r.n,'station:'+id)).join('');if(b.id==='kitchen')controls+=actionButton('吃椰子 · 回血 15 / 恢复体力','food:椰子',(state.bag['椰子']||0)<1)+actionButton('吃椰子饭 · 回血 50','food:椰子饭',(state.bag['椰子饭']||0)<1)+actionButton('吃烤鱼 · 回血 35','food:烤鱼',(state.bag['烤鱼']||0)<1)}if(b.id==='airport')controls=actionButton('制造航空炸弹 · 铁锭 2 + 木炭 3 + 石料 2','airbombmake')+(state.aircraft?actionButton('登上飞机 · 需靠近飞机','airboard')+actionButton('加航空燃油 50 · ◈ 40','airfuel')+actionButton('拖回机场 · ◈ 30（需离机）','airrecall'):actionButton('组装螺旋桨飞机 · 木板 30 + 铁锭 15 + 水晶 3','airbuild'))+'<p>跑道在 X -80 / Z 330。W/S 油门，A/D 转向，↑/↓ 俯仰；速度达到 100 km/h 后抬头起飞。平缓接地，停稳后按 E 下机。</p>';if(b.id==='sawmill'||b.id==='craftbench')controls=actionButton('打开九宫格配方 · 多种物品合成','recipes:'+b.id);if(b.id==='forge')controls=actionButton('铁矿 3 + 木头 1 → 铁锭 1','iron')+actionButton('锻造精钢战镐 · 铁锭 5 + 木板 3','forge1',state.weapon>=1)+actionButton('锻造水晶长矛 · 铁锭 8 + 水晶 3 + 木板 4','forge2',state.weapon>=2);if(b.id==='dock')controls=(state.boatOwned?actionButton(sailing?'靠岸下船':'登上帆船','board'):actionButton('造帆船 · 木板 14 + 铁锭 5','boat'))+(state.boatOwned?actionButton('召回帆船到码头 · ◈ 20','recall'):'')+actionButton('朝向星辉岛','island')+actionButton('码头垂钓 · 每 8 秒一竿','fish')+'<p>帆船靠近码头后可按 E 登船；WASD 驾船，E 靠岸下船。星辉岛位于 X 850 / Z 850。</p>';if(b.id==='turret')controls=actionButton('装填 12 发石弹 · 木头 2 + 石料 1','ammo')+`<p>剩余弹药 ${state.ammo} · 自动防御 140 米范围，每发 25 伤害。</p>`;if(b.id==='garden'){let left=state.gardenPlanted?Math.max(0,Math.ceil((75000-(Date.now()-state.gardenPlanted))/1000)):0;controls=(state.gardenPlanted?actionButton(left?'生长中 · 约 '+left+' 秒':'采收成熟作物','harvest',left>0):actionButton('播种 · 种子 1','plant'))+actionButton('购买种子 3 · ◈ 10','seeds')+actionButton('制作药草汤 · 水果 1 + 药草 2','soup')+actionButton('吃水果 · 回血 25','fruit',(state.bag['水果']||0)<1)+actionButton('喝药草汤 · 回血 60','eatSoup',(state.bag['药草汤']||0)<1)+`<p>种子 ${state.bag['种子']||0} · 水果 ${state.bag['水果']||0} · 谷物 ${state.bag['谷物']||0} · 药草 ${state.bag['药草']||0} · 药草汤 ${state.bag['药草汤']||0}</p>`}if(b.id==='museum')controls=`<p>已展示 ${Object.values(state.museum).filter(Boolean).length} / 7　${state.museumAwarded?'🏆 地质收藏家已解锁':'集齐奖励：600 金币 + 收藏奖杯'}</p>`+kinds.slice(0,7).map((k,i)=>actionButton((state.museum[i]?'取回 ':'展示 ')+k.name+' · '+k.item,'museum'+i,!state.museum[i]&&(state.bag[k.item]||0)<1)).join('');if(b.id==='watchtower')controls=actionButton(onTower?'攀梯下塔':'攀梯登塔 · 需走到塔下','climb')+actionButton('使用望远镜标记矿点与洞穴','mark',!onTower)+state.markedOre.map((m,i)=>actionButton('追踪 '+kinds[m.type].name+' · '+Math.round(m.x)+' / '+Math.round(m.z),'ore'+i)).join('');if(facilitySession==='basic')controls='';if(b.id==='airport')controls=actionButton('前往机场 · 施工接驳','airvisit')+controls;controls+=actionButton('定位并朝向建筑','track'+b.id)}return `<div class="buildingcard"><strong>${b.icon} ${b.name} <small>${built?'✓ 已建成':'待建造'}</small></strong><p>${b.description}</p>${built?'':'<p>材料：'+costText(b.cost)+(b.id==='airport'?' · 背包＋储物箱合计：'+Object.entries(b.cost).map(([k,n])=>k+' '+airportStock(k)+' / '+n).join('，'):'')+'</p>'}<div class="buildingactions">${built?controls:actionButton('建造 '+b.name+(b.id==='airport'?'（含飞机）':''),'build'+b.id)}</div></div>`}).join('');p.querySelectorAll('[data-building-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.buildingAction;if(a==='airvisit'){visitAirport();return}else if(a==='airbombmake')makeAerialBomb();else if(a==='airbuild')buildAircraft();else if(a==='airfuel')fuelAircraft();else if(a==='airrecall')recallAircraft();else if(a==='airboard'){if(boardAircraft()){closeMenu();return}}else if(a.startsWith('recipes:')){facilityFocus=a.slice(8);workshopFilter='全部';workshopRecipe=null;$('.menuhead h2').textContent=siteFor(facilityFocus).name;}else if(a.startsWith('station:'))stationProduce(a.slice(8));else if(a.startsWith('food:'))eatFood(a.slice(5));else if(a==='all'){facilityFocus=facilitySession==='basic'?null:facilitySession;$('.menuhead h2').textContent='探险者营地';}else if(a.startsWith('build'))buildStructure(a.slice(5));else if(a==='plank'||a==='iron')processMaterial(a);else if(a==='forge1'||a==='forge2')forgeWeapon(+a.slice(-1));else if(a==='boat')makeBoat();else if(a==='recall')recallBoat();else if(a==='island'){state.trackedIsland=true;state.trackedFrontier=null;state.trackedBuilding=null;state.trackedCave=null;state.trackedOre=null;yaw=Math.atan2(state.x-850,state.z-850);pitch=0;buildMessage='已朝向东南方的星辉岛。先到码头登船，再驾船出发。';}else if(a==='board'){if(boardBoat()){closeMenu();return}}else if(a==='ammo')makeAmmo();else if(a==='plant')plantGarden();else if(a==='harvest')harvestGarden();else if(a==='soup')makeSoup();else if(a==='fruit')eatFood('水果');else if(a==='eatSoup')eatFood('药草汤');else if(a==='seeds'){if(state.money>=10){state.money-=10;state.bag['种子']=(state.bag['种子']||0)+3;buildMessage='购买了 3 颗种子。'}else buildMessage='需要 10 金币。'}else if(a.startsWith('museum'))putMuseum(+a.slice(6));else if(a==='climb'){if(startClimb()){closeMenu();return}}else if(a==='mark')markFromTower();else if(a==='fish')dockFish();else if(a.startsWith('track')){state.trackedIsland=false;state.trackedBuilding=a.slice(5);state.trackedFrontier=null;state.trackedCave=null;state.trackedOre=null;let site=siteFor(state.trackedBuilding);yaw=Math.atan2(state.x-site.x,state.z-site.z);pitch=0;buildMessage='已朝向 '+site.name+'，关闭面板后向前探索。'}else if(a.startsWith('ore')){state.trackedIsland=false;state.trackedOre=state.markedOre[+a.slice(3)];state.trackedFrontier=null;state.trackedBuilding=null;state.trackedCave=null;yaw=Math.atan2(state.x-state.trackedOre.x,state.z-state.trackedOre.z);pitch=0;buildMessage='已朝向标记的矿点。'}hud();save();renderBuildings()})}
function dockFish(){let p=siteFor('dock');if(!state.buildings.dock||Math.hypot(state.x-p.x,state.z-p.z)>32){buildMessage='需要走到码头上才能垂钓。';return false}if(Date.now()<fishReady){buildMessage='鱼还没上钩，等 '+Math.ceil((fishReady-Date.now())/1000)+' 秒再试。';return false}fishReady=Date.now()+8000;state.bag['小鱼鱼获']=(state.bag['小鱼鱼获']||0)+1;buildMessage='钓到一条小鱼！鱼获已放入背包，可出售 4 金币。';return true}
function buildingPart(g,w,h,d,x,y,z,color=0xcba278){let m=mesh(new THREE.BoxGeometry(w,h,d),color,g);if(color===0xcba278)m.material=woodMat;else if(color===0x696d65||color===0x71746a)m.material=brickMat;else if(color===0x818d87||color===0x65716c||color===0x626d65)m.material=ironMat;else if(color===0x536f64||color===0x4d7163)m.material=roofMat;m.position.set(x,y,z);return m}
