function restoreRockVisual(r){if(r.visualOriginal){r.stone.geometry.dispose();r.stone.geometry=r.visualOriginal.geo;r.stone.scale.copy(r.visualOriginal.scale);r.stone.position.y=r.visualOriginal.y;r.visualOriginal=null}r.chipStage=0;for(let m of r.model.children)m.visible=true}
function attack(){if(!started||paused)return;if(farmAction33())return;if(strikeWild33())return;if(mineAttack31())return;if(!state.dimension&&(!heldItem()||heldItem()==='骨镐')&&pitch<-.55&&!selected&&digGround26())return;if(placeBlueprint29())return;if(state.creative29&&state.dimension&&heldItem()&&!isShovel26(heldItem())){if(cooldown<=0){cooldown=.3;if(!pickLooseItem())placeHeldItem()}return;}if(isShovel26(heldItem())){if(state.dimension)notice('切回快捷栏 1，使用镐采集晶体。');else digGround26();return}if(strikeExtras())return;if(typeof machineMode!=='undefined'&&machineMode){if(playing&&!paused)fireAdvanced();return}if(!playing||paused||cooldown>0||survey||climbing||palmClimb||flying)return;if(pickLooseItem())return;if(heldItem()&&!boneWeapon33(heldItem())){cooldown=.3;placeHeldItem();return}if(selected?.obj.kind==='facility'){openFacility(selected.obj.id);return}if(selected?.obj.kind==='treasure'){openTreasure(selected.obj);return}cooldown=.52;swing=.46;beep(170,.08);if(!selected){notice('对准附近的岩石、树干或鱼再敲击 · 有效距离 '+weapons[state.weapon].reach+' m',1.4);return}pendingStrike={obj:selected.obj,hit:selected.hit.clone(),time:.18}}
function resolveStrike(strike){let o=strike.obj;if(o.dead||Math.hypot(state.x-o.x,state.z-o.z)>weapons[state.weapon].reach+3)return;let damage31=strikeDamage31();o.hp-=armoredDamage33(o,damage31);let p=strike.hit;burst(p.x,p.y,p.z,o.kind==='tree'?0xb48652:typeof o.type==='number'?kinds[o.type].color:0xb4e2d3,8,6);if(typeof o.type==='number')damageRockVisual(o,p);let el=document.createElement('div');el.className='gain';el.textContent='−'+damage31;document.body.append(el);setTimeout(()=>el.remove(),1000);if(o.hp<=0){if(o.kind==='tree'){o.dead=elapsed+180;syncCoconuts(o);state.felled++;fallingTrees.push({tree:o,time:0});let stump=mesh(new THREE.CylinderGeometry(.55,.7,.65,7),0x9e7851);stump.material=woodMat;stump.position.set(o.x,o.baseY+.3,o.z);o.stump=stump;notice('树干断裂！木头即将掉落，走到树根旁拾取。');hud();save();return}o.dead=elapsed+90;o.model.visible=false;if(typeof o.type==='number'){let k=kinds[o.type],n=1+Math.floor(rand()*3);addOreDrop(k.item,n,p.x,p.y,p.z);let gold=Math.round(k.value*(.8+rand()*.5));state.money+=gold;state.mined++;discoverRock(o.type);state.catalog[o.type].count++;notice(`${k.name}完全碎裂！矿物落在地面，金币 +${gold}`);beep(680,.2)}else{if(o.guardian)state.caveGuards[o.caveId]=true;let item=o.type==='鲸鱼'?'鲸鱼战利品':(o.type==='鲨鱼'||o.guardian)?'鲨鱼鱼获':'小鱼鱼获';state.bag[item]=(state.bag[item]||0)+1;state.kills++;awardMagic31(12);notice(`捕获${o.type}！获得 ${item} × 1，可在背包出售 ◈ ${value(item)}`);if(o.guardian)notice('岩甲鲨已击败！获得鲨鱼鱼获，可以去洞底打开宝箱了。',5);beep(500,.2)}hud();save()}}

function renderAtlas(){let p=$('#panel'),found=Object.keys(state.catalog).length;p.innerHTML=`<div class="craftintro"><strong>矿石图鉴 ${found} / ${kinds.length}　·　藏宝洞穴 ${state.caveVisits.length} / ${caveDefs.length}</strong><p>准星看到矿石即可记录。首次成功开采后，可领取一次研究奖励。旧背包中的矿石也会登记为已发现。</p></div><div class="atlascards">`+kinds.map((k,i)=>{let e=state.catalog[i];return `<div class="atlascard ${e?'known':''}"><span style="color:${e?'#'+k.color.toString(16).padStart(6,'0'):'#728776'}">▲</span><div><strong>${k.name}</strong><small>${e?'已发现 · 开采 '+e.count+' 次':'尚未发现'} · 耐久 ${k.hp}</small><p>${atlasHints[i]}</p><button data-atlas="${i}" ${!e||e.count<1||state.catalogRewards[i]?'disabled':''}>${state.catalogRewards[i]?'✓ 研究奖励已领取':'首次开采奖励 ◈ '+atlasRewards[i]}</button></div></div>`}).join('')+'</div><h4 class="exhibittitle">藏宝洞穴 · 从南侧入口进入</h4>'+caveDefs.map(c=>`<div class="cavecard"><strong>◈ ${c.name}　${state.caveOpened[c.id]?'✓ 宝藏已取':state.caveGuards[c.id]?'守卫已击败':state.caveVisits.includes(c.id)?'已发现':'待探索'}</strong><p>${c.hint}<br>入口坐标 X ${c.x} / Z ${c.z+27} · 守卫耐久 ${c.id==='breeze'?180:320}<br>宝箱奖励：◈ ${c.gold} + ${Object.entries(c.loot).map(([k,n])=>k+' × '+n).join('、')}<br>建议携带精钢战镐或更好的武器。</p><button data-track="${c.id}">${state.trackedCave===c.id?'朝向入口':'追踪并朝向入口'}</button></div>`).join('');p.querySelectorAll('[data-atlas]').forEach(b=>b.onclick=()=>{claimAtlas(+b.dataset.atlas);hud();save();renderAtlas()});p.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{let c=caveDefs.find(c=>c.id===b.dataset.track);state.trackedIsland=false;state.trackedCave=c.id;state.trackedFrontier=null;state.trackedBuilding=null;state.trackedOre=null;yaw=Math.atan2(state.x-c.x,state.z-c.z-27);pitch=0;hud();save();renderAtlas();notice('已朝向'+c.name+'的南侧入口，关闭面板后向前探索。',5)})}
for(let i=0;i<kinds.length;i++)if((state.bag[kinds[i].item]||0)>0&&!state.catalog[i])state.catalog[i]={seen:true,count:0};
function value(item){if(item==='地下辉银三角岩')return 180;if(item==='地心蓝晶三角岩')return 240;if(item==='远古曜金三角岩')return 320;return ({'绯樱晶瓣':90,'青穹羽晶':120,'赤焰晶核':180,'虚空结晶':260,'椰子':3,'木炭':5,'抛光宝石':140,'椰子饭':22,'烤鱼':15,'烤鲨鱼肉':28,'面粉':4,'面包':12,'谷物':3,'木头':2,'木板':6,'铁锭':18,'种子':2,'水果':4,'药草':5,'药草汤':18,'小鱼鱼获':4,'鲨鱼鱼获':18,'鲸鱼战利品':55})[item]??recipes.find(r=>r.name===item)?.value??(kinds.find(k=>k.item===item)?.value*2||10)}function renderPanel(){if(tab==='gear33'){renderGear33();return}if(tab==='magic31'){renderMagic31();return}if(tab==='loom31'){renderLoom31();return}if(tab==='creative29'){renderCreative29();return}if(tab==='rooms'){renderAnnexMenu();return}if(tab==='dimensions'){renderDimensions();return}if(state.dimension&&!['bag','shop','guide'].includes(tab)){$('#panel').innerHTML='<p class=guide>请先通过返回门回到海岛，再操作营地设施。</p>';return}if(tab==='crew'){renderCrew();return}updateAccessTabs();$('#menu').classList.remove('workshop-menu');if(['storage','campfire','home','weather'].includes(tab)){renderSurvivalPage();return}if((tab==='build'&&!facilitySession)||(tab==='craft'&&!['craft','craftbench'].includes(facilitySession))){renderLockedWorkbench();return}let p=$('#panel');if(tab==='bag'){let entries=Object.entries(state.bag).filter(([k,v])=>v>0);p.innerHTML=entries.length?entries.map(([k,v])=>`<div class="item"><div><strong>◆ ${k} × ${v}</strong><small>每件 ${value(k)} 金币 · 全部价值 ${value(k)*v}</small></div><div>${isEdible(k)?`<button data-consume="${k}">食用 / 使用</button>`:''}<button data-sell="${k}">出售这组</button></div></div>`).join('')+'<button class="primary" id="sellall">出售矿物与鱼获（保留建材、食物与手作） →</button>':'<div class="empty">背包还空着。<br><br>走近岩石，准星对准它，按 F 或左键采集。</div>'}else if(tab==='shop'){p.innerHTML=weapons.map((w,i)=>`<div class="item"><div><strong class="weapon-name">${weaponIcon(i,44)} ${w.name}</strong><small>${w.damage} 伤害 · ${w.reach} m 距离 · 永久装备</small></div><button data-buy="${i}" ${i<=state.weapon?'disabled':''}>${i===state.weapon?'当前装备':i<state.weapon?'已拥有':'◈ '+w.price}</button></div>`).join('')+'<div class="item"><div><strong>✚ 海岛急救药</strong><small>恢复 60 点生命</small></div><button id="heal">◈ 40</button></div>'}else if(tab==='expedition'){renderExpedition();return}else if(tab==='build'){renderBuildings();return}else if(tab==='atlas'){renderAtlas();return}else if(tab==='craft'){renderCraftPanel();return}else if(tab==='base'){p.innerHTML=`<div class="basevisual"><h3>⌂ 微风营地 · 等级 ${state.base}</h3><p>营火是开局赠送的设施，靠近即可持续回血。<br>升级会扩大室内空间，增加楼层并把家具布置在屋内；院子平台保持原有大小。<br>本级添置：${furnishingNames[state.base-1]}。${state.base<6?'下级添置：'+furnishingNames[state.base]+'。':'家具已全部解锁。'}<br>室内总面积 ${(12+(state.house.size-1)*4)*(11+(state.house.size-1)*3)*state.house.floors} m² · 距离营地 ${Math.round(Math.hypot(state.x-camp.x,state.z-camp.z))} m<br>探索 ${state.visited.length} 个区域 · 开采 ${state.mined} 块岩石 · 击退 ${state.kills} 只海兽</p></div><button class="primary" id="expand" ${facilitySession!=='basic'?'disabled':''}>${facilitySession!=='basic'?'请到合成台扩建':state.base>=6?'✓ 基地已经升至最高级':'扩充基地 · ◈ '+state.base*240}</button><button class="primary" id="home">安全返回营地 · ◈ 30</button>`}else p.innerHTML='<div class="guide"><h3>潜水、农耕与骨器时代</h3><p>进入足够深的海水后，按 O 或点潜水按钮下潜；Q 继续下潜，空格上浮。留意氧气条，浮出水面恢复氧气。潜水气瓶放在背包中可延长水下时间。</p><p>底部魔法条记录击杀获得的魔法值。必须先在合成台建造魔法台，之后才能通过 M 或点击魔法条施法。</p><p>营地外有羊、牛与野生番茄、香果。挖掉植物取得种子；合成石锄或骨锄，在营地外陆地上左键开垦，再拿种子对准空耕地播种，约 2 分钟成熟。成熟收获会得到果实与新种子。</p><p>击杀遗迹巡游和深层矿区的骷髅怪获得骨头。合成台可制作骨剑、骨锥、骨镐、骨铲、骨锄、骨块和骨盔甲。石铲既可用闪长岩，也可用普通石料配木棍制作。点击左侧盔甲按钮装备盔甲，也可给 6 米内的生物穿甲；受击消耗耐久。</p><h3>魔法与无尽矿层</h3><p>点击开启冒险后，依次通过弹窗选择设备、确认设备、选择模式。模式绑定存档，之后不能更改。</p><p>开局营地只保留合成台。木料加工、工具和建筑方块使用摆放配方；设施建造也从同一合成台进入。织布机可织布、染色和制作旗帜。</p><p>击杀生物获得魔法能量。M 或左侧魔法按钮打开施法页；武器强化必须走到魔法合成器操作。施法和强化攻击都会消耗能量。</p><p>装备铲子低头挖土，遇到石头切回快捷栏 1 的镐或锤。挖开约 6 米浅层后进入深层矿区。深层用镐敲矿，低头连续敲碎底部石层可继续下掘，每次下降 3 米，没有预设底部。地下三角岩更值钱，并伴生铁矿、水晶、古代齿轮；30 米后有外星金属，60 米后有铀矿石。上方升降索按钮可返回地表。</p><p>木材、砖石、玻璃与布料方块可用来建房；方块摆放自动对齐水平网格，顶面可以继续叠放。创造模式可直接领取材料。</p><b>探索主岛、建造营地，驾船前往星辉岛。</b><p>第一人称：WASD 移动，鼠标转头；按空格跳跃，Shift 奔跑。门口按 E 开关木门，直接走过门口即可进出房屋；对准沙发按 E 坐下、再按 E 起身。空手使用营火可取暖回血，手持生鱼则放上烤架。点击画面可锁定鼠标，Esc 释放。若不锁定，也可按住右键拖动转头。方向键同样能转头。</p><p>快捷物品栏：按 1—9 或滚轮切换，背包中可选择「拿在手里」。拿着鱼、木头等物品，对准 5 米内的桌面或地面，左键 / E 直接放下；对准摆放物按 E 拿回，G 食用手中熟食。室内沿左侧楼梯走动即可上下楼，右侧是卫生间。</p><p>iPad：左下摇杆移动，右半屏滑动转头，右下按钮攻击和跳跃。</p><p>用准星对准岩石，走到有效距离内按 F 或左键。地图上有 12 种矿岩，碎裂后随机掉落矿物和金币，约 90 秒后重生。</p><p>按 B 可整理背包、交易和买武器；扩建与建筑制造需要在基础工作台操作。营火附近自动回血。R 只会朝向营地，不会传送。V 进入灵魂勘探：身体留在原地，WASD 自由飞行，空格上升、Q 下降、Shift 加速；青色人形与标记显示身体位置，V 原地归位。</p><p>鱼会周期性跃出海面并溅起水花。鲨鱼和鲸鱼会在近海追击你，近岸时还会跃向沙滩。死亡会在营地复活并失去 15% 金币。</p><p>椰子：走近棕榈树按 E 爬树，到达树冠按 E 摘取并下树，椰子约 3 分钟后长回。砍树：准星对准树干，按 F 挥镐。树倒下后木头落在树根旁，走近自动拾取，树木约 3 分钟后长回。</p><p>手作：走近合成台制作工艺品和木制展架，再在合成台的展示页面把工艺品放到展架上。展架与展品会真实出现在基地，展示中的物品不会被出售。</p><p>捕鱼：击败小鱼或鲨类可获得鱼获，在背包出售。小鱼 4 金币、鲨鱼 18 金币、鲸鱼战利品 55 金币。</p><p>设施操作：建成后靠近，点击设施旁的「点击使用」按钮进入专属页面。电脑按 Esc 释放鼠标，也可用准星对准设施后点左键或按 F。</p><p>建筑：靠近营地赠送的合成台，点击建造与生产。木板在合成台制作，铁锭在熔炼炉制作。码头建成后可造帆船，靠近船按 E 上下船。星辉岛在东南方 X 850 / Z 850。瞭望塔脚下按 E 攀登，到顶后可标记矿点。</p><p>遗迹与航空：J 打开手记，追踪风蚀石殿、观测站和海岸驿站。机场在 X -80 / Z 330，建成即自带满油飞机；W/S 调整油门，A/D 转向，↑/↓ 俯仰，达到 100 km/h 后抬头起飞。减油门平缓降落，空格刹车，停稳后 E 下机。</p><p>先进装备：基础工作台可建造重型工程工坊与卫星发射中心。矿井采铀、废弃研究区回收外星金属，火山采岩浆，在工坊制作外星合金与能量模块，再制造坦克、大炮、导弹和核弹。卫星入轨后可扫描稀有矿。J 查看远征地点与坐标，装备操作时 1/2/3 选弹，左键发射、E 离开。</p><p>推荐路线：微风海岸 → 椰风密林 → 水晶峡谷 → 远古山脊 → 鲸落海湾。每个方向都有不同的矿石、地形和地标。</p></div>';p.querySelectorAll('[data-consume]').forEach(b=>b.onclick=()=>{eatFood(b.dataset.consume);notice(buildMessage);refresh()});if(tab==='shop')appendShop26(p);p.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sell(b.dataset.sell));p.querySelector('#sellall')?.addEventListener('click',()=>sell());p.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let i=+b.dataset.buy,w=weapons[i];if(state.money<w.price)return notice('金币不足，先出售一些矿物或鱼获');state.money-=w.price;state.weapon=i;updateTool();notice('已装备：'+w.name);refresh()});p.querySelector('#heal')?.addEventListener('click',()=>{if(state.hp>=healthLimit())return notice('生命值已满');if(state.money<40)return notice('需要 40 金币');state.money-=40;state.hp=Math.min(healthLimit(),state.hp+60);refresh()});p.querySelector('#expand')?.addEventListener('click',()=>{if(facilitySession!=='basic')return notice('请到合成台扩建营地。');if(state.base>=6)return;if(state.money<state.base*240)return notice('扩建需要 '+state.base*240+' 金币');state.money-=state.base*240;state.base++;updateBase();notice('营地扩建完成：'+furnishingNames[state.base-1]+'已放入屋内，室内空间与楼层已同步升级');refresh()});p.querySelector('#home')?.addEventListener('click',()=>{if(state.dimension){leaveDimension();return}if(flying)return notice('请先降落并离开飞机。');if(state.insideHouse){leaveHouse();return}if(state.money<30)return notice('需要 30 金币');invulnerable=5;sailing=false;climbing=0;palmClimb=null;onTower=false;state.money-=30;state.x=camp.x;state.z=camp.z+16;footY=terrain(state.x,state.z);vy=0;yaw=0;pitch=0;notice('已回到营火旁');refresh()})}
function refresh(){hud();renderPanel();save()}function sell(item){let gold=0;for(let k of Object.keys(state.bag))if(item?k===item:(!keptResources.includes(k)&&!recipes.some(r=>r.name===k))){gold+=state.bag[k]*value(k);state.bag[k]=0}state.money+=gold;notice(gold?'交易成功，获得 '+gold+' 金币':'还没有可出售的矿物或鱼获');refresh()}
function clearInput(){for(let k in keys)keys[k]=false;attacking=false;moveStick.x=moveStick.y=0;$('#joystick i').style.transform=''}function openMenu(){if(!started)return;paused=true;menuOpen=true;clearInput();document.exitPointerLock?.();renderPanel();hud();$('#menu').showModal();$('#resume').hidden=true}function closeMenu(){facilitySession=null;if($('#menu').open)$('#menu').close();menuOpen=false;paused=false;playing=true;last=performance.now();if(!touch)try{canvas.requestPointerLock?.()?.catch?.(()=>{})}catch{}}
function resume(){paused=false;playing=true;$('#resume').hidden=true;last=performance.now();if(!touch)try{let r=canvas.requestPointerLock?.();r?.catch?.(()=>notice('按住右键拖动也可以转头'))}catch{}}function pause(){if(!started||menuOpen)return;paused=true;clearInput();document.exitPointerLock?.();$('#resume').hidden=false;save()}
