function parkedAircraftBlocks(x,z){let a=state.aircraft;if(!a||flying||footY>a.y+2.4)return false;let dx=x-a.x,dz=z-a.z,side=dx*Math.cos(a.yaw)-dz*Math.sin(a.yaw),fore=dx*Math.sin(a.yaw)+dz*Math.cos(a.yaw);return Math.abs(side)<1.1&&Math.abs(fore)<3.5}
function boardAircraft(){let a=state.aircraft;if(!a||flying||survey||sailing||palmClimb||climbing||onTower)return false;if(Math.hypot(state.x-a.x,state.z-a.z)>7){buildMessage='先到机场跑道，靠近飞机再登机。';return false}flying=true;state.flying=true;clearInput();yaw=a.yaw;pitch=a.pitch;notice('已登机：W/S 调油门，A/D 转向，↑ 抬头 / ↓ 低头，空格地面刹车，停稳后 E 下机。',10);return true}
function exitAircraft(){let a=state.aircraft;if(!flying||!a)return false;if(!a.grounded||a.speed>3){notice('飞机需着陆并停稳后才能下机。');return false}flying=false;state.flying=false;state.x=a.x+4.5;state.z=a.z;footY=terrain(state.x,state.z)+.15;vy=0;pitch=0;yaw=a.yaw;clearInput();notice('已安全离开飞机。');save();return true}
function resetAircraft(){let a=state.aircraft;Object.assign(a,{x:-80,z:375,y:15.1,yaw:0,pitch:0,speed:0,throttle:0,grounded:true});state.hp=Math.max(1,state.hp-20);notice('硬着陆，救援队已将飞机拖回机场。生命 -20；可重新滑跑起飞。',8)}
const cockpit=new THREE.Group();camera.add(cockpit);cockpit.visible=false;function cockpitPart(w,h,d,x,y,z,color){let m=mesh(new THREE.BoxGeometry(w,h,d),color,cockpit);m.position.set(x,y,z);m.castShadow=false;return m}cockpitPart(1.6,.24,.15,0,-.57,-1.12,0x3c4c48);for(let x of [-.72,.72]){let strut=cockpitPart(.035,1.9,.035,x,.2,-1.15,0x91a49b);strut.rotation.z=x*.2}for(let x of [-.25,.12,.4]){let gauge=new THREE.Mesh(new THREE.CircleGeometry(.075,20),new THREE.MeshBasicMaterial({color:0xd6ddbb}));gauge.position.set(x,-.51,-1.035);cockpit.add(gauge)}
function updateAircraft(dt){let a=state.aircraft;if(!a)return;if(flying){let turn=(keys.KeyA?1:0)-(keys.KeyD?1:0)-moveStick.x,tilt=(keys.ArrowUp?1:0)-(keys.ArrowDown?1:0)-moveStick.y;a.throttle=Math.max(0,Math.min(1,a.throttle+((keys.KeyW?1:0)-(keys.KeyS?1:0))*dt*.45));if(a.fuel<=0)a.throttle=0;let target=a.throttle*52,delta=Math.max(-12*dt,Math.min(8*dt,target-a.speed));a.speed=Math.max(0,a.speed+delta);if(a.grounded&&keys.Space)a.speed=Math.max(0,a.speed-25*dt);a.yaw+=turn*dt*.55*Math.min(1,a.speed/12);a.pitch=Math.max(-.48,Math.min(.48,a.pitch+tilt*dt*.3));a.bank=THREE.MathUtils.lerp(a.bank||0,-turn*.22,dt*3);if(a.grounded&&a.speed<28)a.pitch=Math.min(.06,a.pitch);let steps=Math.max(1,Math.ceil(a.speed*dt/.5));for(let i=0;i<steps;i++){let step=dt/steps,nx=a.x-Math.sin(a.yaw)*a.speed*step,nz=a.z-Math.cos(a.yaw)*a.speed*step,ground=terrain(nx,nz)+1.1,climb=Math.sin(a.pitch)*a.speed-Math.max(0,27-a.speed)*.45,ny=a.y+climb*step;if(a.grounded&&a.speed<28)ny=Math.min(a.y,ny);let obstruction=!a.grounded&&(obstacles.some(t=>!t.dead&&Math.hypot(nx-t.x,nz-t.z)<2&&ny<t.baseY+10*t.scale)||rocks.some(r=>!r.dead&&Math.hypot(nx-r.x,nz-r.z)<r.size&&ny<r.model.position.y+r.size*2)||solidAt(nx,nz,ny-.5));if(Math.abs(nx)>1120||Math.abs(nz)>1120||obstruction){resetAircraft();break}if(ny<=ground){if(!a.grounded&&(a.speed>39||a.pitch<-.21||terrain(nx,nz)<.3)){resetAircraft();break}ny=ground;a.grounded=true;if(a.pitch<0)a.pitch=0}else a.grounded=false;a.x=nx;a.z=nz;a.y=Math.min(230,ny)}if(a.y>=229&&a.pitch>0)a.pitch=0;a.fuel=Math.max(0,a.fuel-dt*(.015+a.throttle*.045));state.x=a.x;state.z=a.z;footY=a.y;vy=0;grounded=false;yaw=a.yaw;pitch=a.pitch;$('#flight-speed').textContent=Math.round(a.speed*3.6)+' km/h';$('#flight-alt').textContent=Math.round(a.y-terrain(a.x,a.z))+' m';$('#flight-fuel').textContent=Math.ceil(a.fuel)+'%';$('#flight-route').textContent=state.flightDestination?state.flightDestination.name+' · '+Math.round(Math.hypot(a.x-state.flightDestination.x,a.z-state.flightDestination.z))+' m · 航向 '+Math.round((360-Math.atan2(a.x-state.flightDestination.x,a.z-state.flightDestination.z)*180/Math.PI+360)%360)+'°':'J 选择航空目的地 · X 投弹';$('#flight-state').textContent=a.grounded?'地面 · 达到 100 km/h 后 ↑ 抬头':'飞行 · 平缓接地，S 减油门';}if(aircraftModel){aircraftModel.visible=!flying;aircraftModel.position.set(a.x,a.y,a.z);aircraftModel.rotation.set(a.pitch,a.yaw,a.bank||0,'YXZ');aircraftModel.userData.propeller.rotation.z+=dt*a.throttle*60}$('#flight-hud').hidden=!flying;$('#flight-more').onclick=()=>{a.throttle=Math.min(1,a.throttle+.2)};$('#flight-less').onclick=()=>{a.throttle=Math.max(0,a.throttle-.2)}}
