// Real-time sun, moon, stars and seabirds; clouds continue drifting with the coastal wind.
const starPositions=[];for(let i=0;i<650;i++){let a=rand()*Math.PI*2,y=160+rand()*740,r=Math.sqrt(950*950-y*y);starPositions.push(Math.cos(a)*r,y,Math.sin(a)*r)}const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPositions,3));const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xe0e8ff,size:1.7,transparent:true,opacity:0,depthWrite:false,fog:false}));scene.add(stars);const sunDisc=new THREE.Mesh(new THREE.SphereGeometry(15,16,12),new THREE.MeshBasicMaterial({color:0xffe5ad,fog:false})),moonDisc=new THREE.Mesh(new THREE.SphereGeometry(10,16,12),new THREE.MeshBasicMaterial({color:0xc7dae3,fog:false}));scene.add(sunDisc,moonDisc);const gulls=[];for(let i=0;i<14;i++){let g=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:0xdfe1d0,roughness:1,side:THREE.DoubleSide});for(let side of [-1,1]){let wing=new THREE.Mesh(new THREE.PlaneGeometry(1.7,.38),mat);wing.rotation.x=-Math.PI/2;wing.position.x=side*.8;g.add(wing)}scene.add(g);gulls.push({g,phase:rand()*Math.PI*2,r:180+rand()*380,h:65+rand()*50})}
function updateSky(){let hour=state.daytime%24,day=Math.max(0,Math.sin((hour-6)/12*Math.PI)),light=.2+.8*day;skyDome.material.color.setRGB(light,light,Math.min(1,light+.08));scene.fog.color.set(0xb7dce6).lerp(new THREE.Color(0x102436),1-day);hemisphere.intensity=.12+day*1.43;sun.intensity=.15+day*3;sun.color.set(day<.3?0xffbc7b:0xffedce);stars.material.opacity=Math.max(0,.85-day*2);stars.position.copy(camera.position);let angle=(hour-6)/12*Math.PI;sun.position.set((survey?spirit.x:state.x)+Math.cos(angle)*180,Math.max(25,Math.sin(angle)*230)+Math.max(0,footY),(survey?spirit.z:state.z)-100);sunDisc.position.copy(camera.position).add(new THREE.Vector3(Math.cos(angle)*820,Math.sin(angle)*820,-280));moonDisc.position.copy(camera.position).add(new THREE.Vector3(-Math.cos(angle)*820,-Math.sin(angle)*820,-280));sunDisc.visible=Math.sin(angle)>-.035;moonDisc.visible=day<.35;gulls.forEach((bird,i)=>{let a=elapsed*.045+bird.phase;bird.g.position.set(Math.cos(a)*bird.r,bird.h+Math.sin(a*2)*4,420+Math.sin(a)*bird.r*.6);bird.g.rotation.y=-a;bird.g.children.forEach((wing,j)=>wing.rotation.z=Math.sin(elapsed*3+i)*(j?-.22:.22))})}
function updateExpedition(dt){updateAircraft(dt);for(let d of ruinDefs)if(!state.ruinSeen[d.id]&&Math.hypot(d.x-state.x,d.z-state.z)<40){state.ruinSeen[d.id]=true;notice('发现野外遗迹：'+d.name+' · J 查看探险手记',7);save()}}
