function sitOnSofa(anchor){if(!state.insideHouse||!anchor?.group.userData.seat)return;let p=anchor.group.localToWorld(new THREE.Vector3(anchor.group.userData.seat.x,.12,anchor.group.userData.seat.z));if(Math.hypot(p.x-state.x,p.z-state.z)>4)return notice('靠近沙发后，按 E 坐下。');seated={x:state.x,z:state.z,y:footY,yaw};state.x=p.x;state.z=p.z;footY=p.y;vy=0;yaw=0;pitch=0;clearInput();notice('已坐在沙发上休息 · 缓慢恢复生命与体力 · E / 移动键起身',5)}
