function updateExperienceHints(){if(!started||paused||survey||flying||menuOpen)return;if(seated)carryHint.textContent='沙发休息中 · 生命与体力恢复 · E / 移动键起身';else if(nearHouseDoor())carryHint.textContent=state.houseDoorOpen?'门已打开 · 直接走过门口 · E 关门':'木门 · E 开门，然后走进去';else if(selected?.obj.id==='campfire')carryHint.textContent=state.cooking?'烤架：'+(Date.now()>=state.cooking.readyAt?'已烤熟 · E 取回':'烤制中 · '+Math.max(1,Math.ceil((state.cooking.readyAt-Date.now())/1000))+' 秒'):heldItem()&&['鲨鱼鱼获','小鱼鱼获'].includes(heldItem())?'E 把手中的生鱼放上烤架':'E 靠火取暖 · 回血、恢复体力'}
