function enterAnnex(id){if(id!=='hall'&&!state.house.rooms[id])return notice('先用金币建造这个房间。');if(seated)standUp();state.extraRoom=id;state.house.level=0;state.x=id==='hall'?80:140+annexDefs.findIndex(d=>d.id===id)*24;state.z=id==='hall'?10:3.5;footY=340.14;vy=0;yaw=0;pitch=0;if(interiorGroup)interiorGroup.visible=true;extraRoomsGroup.visible=true;rebuildSolids();grounded=true;clearInput();notice(id==='hall'?'室内走廊 · 右侧门通往独立房间，南端返回主屋。':annexDefs.find(d=>d.id===id).name+' · 直接从门口走回走廊。',5)}
